// Precompiles schemas/interaction-report.schema.json into one standalone ES module.
// Workers forbid new Function, so Ajv cannot compile at runtime there. The page and the
// Worker both import the same generated file, so there is exactly one validator.
//
// Run with `pnpm build:validators`. The output is committed, and a test checks that
// regenerating it gives byte-identical output.

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";

const root = fileURLToPath(new URL("..", import.meta.url));

export const VALIDATOR_SCHEMA_PATH = "schemas/interaction-report.schema.json";
export const VALIDATOR_OUTPUT_PATH = "public/generated/validate-interaction-report.js";

export function buildValidatorSource(repoRoot = root) {
  const schema = JSON.parse(readFileSync(join(repoRoot, VALIDATOR_SCHEMA_PATH), "utf8"));
  const ajv = new Ajv2020({ code: { source: true, esm: true, lines: true }, allErrors: true });
  ajv.compile(schema);
  const body = standaloneCode(ajv, { validateInteractionReport: schema.$id });
  return `// Generated by scripts/build-validators.mjs from ${VALIDATOR_SCHEMA_PATH}. Do not edit.\n${body}\n`;
}

if (import.meta.url === pathToFileURL(process.argv[1] || "").href) {
  writeFileSync(join(root, VALIDATOR_OUTPUT_PATH), buildValidatorSource());
  console.log(`wrote ${VALIDATOR_OUTPUT_PATH}`);
}
